function splitFields(text, separator, limit) {
  const cap = limit || Infinity;
  const parts = separator === '' ? Array.from(text) : text.split(separator);
  return parts.filter(part => part !== '' && part !== undefined).slice(0, cap);
}
module.exports = { splitFields };

