const test = require('node:test');
const assert = require('node:assert/strict');
const { splitFields } = require('../src/delimited-fields.cjs');

test("literal separators keep empty fields and honor zero limit", () => {
  assert.deepEqual(splitFields('|oak||pine|', '|'), ['', 'oak', '', 'pine', '']);
  assert.deepEqual(splitFields('oak|pine|elm', '|', 2), ['oak', 'pine']);
  assert.deepEqual(splitFields('oak|pine', '|', 0), []);
  assert.deepEqual(splitFields('oak'), ['oak']);
  assert.deepEqual(splitFields('', ','), ['']);
  assert.deepEqual(splitFields('', ''), []);
});

test("captured groups are output entries including unmatched groups", () => {
  assert.deepEqual(splitFields('oak,12;pine', /(,)|(;)/), ['oak', ',', undefined, '12', undefined, ';', 'pine']);
  assert.deepEqual(splitFields('oak,12;pine', /([,;])/, 3), ['oak', ',', '12']);
});

test("empty string separators use UTF-16 but Unicode regexes use code points", () => {
  assert.deepEqual(splitFields('😀X', ''), ['\ud83d', '\ude00', 'X']);
  assert.deepEqual(splitFields('😀X', /(?:)/u), ['😀', 'X']);
  assert.deepEqual(splitFields('😀X', '', 1), ['\ud83d']);
});

